const result=[];
for(let i=0;i<items.length;i++){
 const mail=items[i];
 for(const [key,b] of Object.entries(mail.binary||{})){
  const name=String(b.fileName||'attachment.pdf');
  if(!name.toLowerCase().endsWith('.pdf') && b.mimeType!=='application/pdf') continue;
  result.push({json:{messageId:mail.json.id||mail.json.messageId||'',subject:mail.json.subject||'',sender:typeof mail.json.from==='string'?mail.json.from:(mail.json.from?.text||''),attachmentKey:key,originalFileName:name},binary:{data:b},pairedItem:{item:i}});
 }
}
return result;

// EDIT THIS NODE: set the Google Drive folder ID and classification rules.
const config={
  driveFolderId:'REPLACE_WITH_DRIVE_FOLDER_ID',
  defaultCurrency:'EUR',
  maxPdfTextChars:100000,
  enableOCR:false, // Optional: connect an OCR endpoint before enabling
  enableAI:false, // Optional: connect an OpenAI-compatible endpoint before enabling
  ocrEndpoint:'https://example.invalid/ocr',
  aiEndpoint:'https://example.invalid/v1/chat/completions',
  reportEmail:'', // Optional: one digest per completed execution
  labelProcessed:'', // Optional Gmail label ID
  labelReview:'', // Optional Gmail label ID
  folderPrefix:'Invoices',
  categories:[
    {name:'Utilities',keywords:['electricity','gas bill','energy invoice','utility']},
    {name:'Internet',keywords:['broadband','internet service','telecom']},
    {name:'Cloud',keywords:['cloud computing','cloud services','hosting','server']}
  ]
};
return {...$input.item,json:{...$input.item.json,config}};

const source=$('Configuration').item;
const cfg=source.json.config;
const raw=String($input.item.json.text||$input.item.json.data||'').slice(0,cfg.maxPdfTextChars||100000).replace(/\r/g,'');
const subject=source.json.subject||'';
const fail=(reason)=>({json:{...source.json,status:'rejected',reason,processedAt:new Date().toISOString()},binary:source.binary});
if(raw.trim().length<40) return fail('PDF has no extractable text (OCR required)');
const lines=raw.split('\n').map(x=>x.trim()).filter(Boolean);
const find=(patterns)=>{for(const p of patterns){const m=raw.match(p);if(m)return m[1].trim();}return '';};
const invoiceNumber=find([/(?:invoice\s*(?:number|no\.?|#)|fattura\s*(?:n\.?|numero)|rechnungsnummer)\s*[:#-]?\s*([A-Z0-9][A-Z0-9\/-]{2,35})/i]);
const dateString=find([/(?:invoice\s*date|data\s*fattura|rechnungsdatum|date\s*of\s*issue)\s*[:\s]*([0-9]{1,4}[.\/-][0-9]{1,2}[.\/-][0-9]{2,4})/i]);
function parseDate(s){
 const p=s.split(/[.\/-]/).map(Number);if(p.length!==3)return '';
 let [a,b,c]=p;let y,m,d;
 if(a>1900){y=a;m=b;d=c}else{d=a;m=b;y=c<100?2000+c:c}
 const dt=new Date(Date.UTC(y,m-1,d));
 return dt.getUTCFullYear()===y&&dt.getUTCMonth()===m-1&&dt.getUTCDate()===d?`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`:'';
}
const invoiceDate=parseDate(dateString);
const dueDate=parseDate(find([/(?:due\s*date|payment\s*due|scadenza(?:\s*pagamento)?|zahlbar\s*bis)\s*[:\s]*([0-9]{1,4}[.\/-][0-9]{1,2}[.\/-][0-9]{2,4})/i]));
function money(s){s=String(s).replace(/[^0-9,.-]/g,'');const comma=s.lastIndexOf(','),dot=s.lastIndexOf('.');
 if(comma>dot)s=s.replace(/\./g,'').replace(',','.');else if(dot>comma)s=s.replace(/,/g,'');
 const v=Number(s);return Number.isFinite(v)?Math.round(v*100)/100:null;
}
const total=find([/(?:grand\s*total|total\s*(?:due|amount|invoice)|amount\s*due|totale\s*(?:fattura|da\s*pagare|complessivo)|gesamtbetrag)\s*[:\s€$]*([0-9][0-9.,]*[.,][0-9]{2})/i]);
const amount=total?money(total):null;
const currency=/\bUSD\b|\$/.test(raw)?'USD':/\bGBP\b|£/.test(raw)?'GBP':/\bEUR\b|€/.test(raw)?'EUR':cfg.defaultCurrency;
const vendorLine=lines.find(x=>/^(?:supplier|vendor|fornitore|seller)\s*:/i.test(x));
const vendor=(vendorLine?vendorLine.replace(/^[^:]+:\s*/,''):lines.find(x=>/[A-Za-z]{3,}/.test(x)&&!/(invoice|fattura|date|data|bill to)/i.test(x))||'').slice(0,80).trim();
const lower=(raw.slice(0,3500)+' '+subject).toLowerCase();
const category=(cfg.categories.find(c=>c.keywords.some(k=>lower.includes(k.toLowerCase())))||{}).name||'Other';
if(!invoiceNumber||!invoiceDate||amount===null||!vendor) return fail('Missing or invalid invoice number, date, total or vendor');
if(amount<0) return fail('Negative total requires manual review');
if(amount>100000000) return fail('Unusually large total requires manual review');
if(dueDate && dueDate < invoiceDate) return fail('Due date precedes invoice date');
const clean=s=>String(s).normalize('NFKD').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').slice(0,65);
const uniqueKey=[clean(vendor).toLowerCase(),clean(invoiceNumber).toLowerCase(),invoiceDate].join(':');
const fileName=`${invoiceDate}_${clean(vendor)}_${clean(invoiceNumber)}.pdf`;
return {json:{...source.json,status:'validated',invoiceNumber,invoiceDate,dueDate,amount,currency,vendor,category,uniqueKey,fileName,processedAt:new Date().toISOString()},binary:source.binary};

const src=$('Parse & validate invoice').item;
if(src.json.status!=='validated'||!src.binary?.data)throw new Error('Missing validated PDF binary');
if(src.json.config.driveFolderId.startsWith('REPLACE_'))throw new Error('Set driveFolderId in Configuration');
return {json:src.json,binary:src.binary};

const src=$('Restore validated PDF').item.json;
const id=$input.item.json.id||$input.item.json.fileId||'';
if(!id)throw new Error('Drive upload returned no file ID');
return {json:{uniqueKey:src.uniqueKey,invoiceNumber:src.invoiceNumber,vendor:src.vendor,invoiceDate:src.invoiceDate,dueDate:src.dueDate||"",amount:src.amount,currency:src.currency,category:src.category,fileName:src.fileName,driveFileId:id,status:'archived',sourceMessageId:src.messageId,processedAt:new Date().toISOString()}};
